"重跑等待确认(秒)": "Chờ xác nhận chạy lại (giây)",
"重跑等待确认需为 {min}-{max} 的整数(秒)": "Thời gian chờ xác nhận chạy lại phải là số nguyên từ {min} đến {max} (giây)",
"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "Thời gian chờ của popup xác nhận loại chạy lại («Chạy lại?»...), mặc định 60 giây: hết đếm ngược mà không có phản hồi thì tự động áp dụng lựa chọn mặc định (thường là «Chạy lại»), pipeline không bị kẹt vì chờ người. Tăng giá trị để có thêm thời gian quyết định, đổi lại khi không có người trực pipeline sẽ chờ lâu hơn ở popup; thời gian chờ ngắn hơn do agent chỉ định vẫn có hiệu lực nhưng không được vượt quá giá trị này. Popup loại ký duyệt (ký tay cổng H) không bao giờ đếm ngược, không bao giờ tự xác nhận nên không bị ảnh hưởng. Cài đặt toàn cục, lưu xong có hiệu lực với các xác nhận phát sinh sau đó.",
"⚙️ Agent 高级设置": "⚙️ Cài đặt nâng cao Agent",
"重跑次数": "Số lần chạy lại",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "Giới hạn số lần agent tự động chạy lại / re-roll, mặc định 0: khi chấm nghiệm thu, thẩm định QA hoặc kiểm tra máy không đạt, Tổng chế tác tự động trả lại kèm ý kiến để làm lại; khi tạo video/ảnh không qua kiểm tra máy thì tự động re-roll. Cùng một tác vụ đạt tới số lần này mà vẫn không qua sẽ được chuyển lên người dùng quyết định thay vì tự thử tiếp; đặt 0 thì tắt hoàn toàn chạy lại tự động (không đạt lần đầu là chuyển lên người). Cài đặt toàn cục, được đưa vào mọi agent qua prompt runtime và ghi đè «tối đa 3 lần» cố định trong tài liệu quy trình; áp dụng cho các lần chạy bắt đầu sau khi lưu.",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "Số lần chạy lại phải là số nguyên từ 0 đến {max} (0 = không tự chạy lại)",
"轮次上限": "Giới hạn lượt",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "Mức trần số lượt hội thoại của engine trong một lệnh công việc, mặc định 250: chỉ áp dụng cho engine claude và grok (tham số headless --max-turns; bỏ trống nghĩa là không giới hạn — chốt chặn này để ngăn vòng lặp mất kiểm soát). Các engine codex/pi/opencode không có tham số này nên không bị ảnh hưởng; deepagents dùng giới hạn đệ quy của chính framework. Khi chạm trần, engine bị cắt ngay và không thể tiếp tục — biên nhận chỉ hiển thị mã thoát 1; sản phẩm đã ghi đĩa vẫn còn nhưng thiếu bước kiểm tra và biên nhận. Với các công đoạn khối lượng lớn (chọn cảnh theo nhóm, cắt hàng loạt), một lệnh gồm hàng chục nhóm khiến 100 lượt là quá ít; nếu vẫn chạm trần, trước hết hãy giảm độ rộng lô phái đơn, sau đó mới tăng giá trị này. Cài đặt toàn cục; áp dụng cho các lần chạy khởi động sau khi lưu.",
"轮次上限需为 {min}-{max} 的整数": "Giới hạn lượt phải là số nguyên từ {min} đến {max}",
"思考深度": "Độ sâu suy nghĩ",
"引擎默认": "Mặc định của engine",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "Cài đặt thống nhất Độ sâu suy nghĩ (Thinking Effort), mặc định «Mặc định của engine»: khi giao việc sẽ được dịch thành tham số cường độ suy luận của từng engine — claude → --effort, codex → model_reasoning_effort (không có max, ánh xạ sang xhigh), pi → --thinking, opencode → --variant (bị bỏ qua nếu mô hình không có mức đó), grok → --reasoning-effort (không có max; ánh xạ sang xhigh), deepagents → reasoning_effort (chỉ kênh đám mây/OpenRouter, không gửi cho mô hình cục bộ); kimi CLI không có tham số tương ứng nên không bị ảnh hưởng. Càng sâu càng ổn định nhưng chậm hơn và tốn token hơn; «Mặc định của engine» không truyền tham số nào, dùng cấu hình riêng của từng engine (như effortLevel trong ~/.claude/settings.json, model_reasoning_effort trong ~/.codex/config.toml). Cài đặt toàn cục, áp dụng cho mọi Agent, có hiệu lực với các lượt chạy khởi động sau khi lưu.",
