",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": ", được đính kèm vào tin nhắn mỗi lần chế độ tự chạy đánh thức Tổng chế tác, nên không mất đi dù phiên được mở lại; phù hợp cho ràng buộc dài hạn, nên viết dạng điều kiện (ví dụ: 「trước khi toàn bộ kịch bản ep01-ep10 hoàn tất, không giao phiếu việc loại thiết lập」); để trống thì không đính kèm",
"在 ep01-ep10 剧本全部完成前,不派设定类工单": "Trước khi toàn bộ kịch bản ep01-ep10 hoàn tất, không giao phiếu việc loại thiết lập",
