"闲置时间(min)": "Thời gian nhàn rỗi (min)",
"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "Thời gian nhàn rỗi: cứ mỗi khoảng này kiểm tra một lần, chỉ khi pipeline nhàn rỗi (không tác vụ đang chạy, không mục chờ xác nhận) mới gửi tin kiểm tra trạng thái, mặc định 5 phút. Ngưỡng: khi mức dùng phiên trong cửa sổ 5 giờ của engine đang dùng của Nhà sản xuất (claude/codex) đạt giá trị này thì lượt đó không gửi; không đọc được mức dùng thì cho qua. Đều là thiết lập toàn cục, áp dụng cho mọi dự án (công tắc ở nút 🤖 trong bảng vận hành, độc lập theo dự án)",
