"Voice Design:按角色嗓音的文字描述生成嗓音样本(人物嗓音设计时用);Voice Clone:按嗓音样本 + 对白文字生成对白。两者按用途自动选择;未配置 Voice Design 时一律走 Voice Clone": "Voice Design: tạo mẫu giọng từ mô tả bằng văn bản về giọng nhân vật (khi thiết kế giọng nhân vật). Voice Clone: tạo lời thoại từ mẫu giọng + văn bản lời thoại. Hai chế độ được chọn tự động theo mục đích; khi chưa cấu hình Voice Design, tất cả dùng Voice Clone",
