"获取;工作流须先在网页端跑通,并把 {{PROMPT}} 等占位符写入对应节点输入位(约定与本地工作流一致),再把工作流 ID 或页面链接粘贴到「添加工作流」验证;国内站与国际站账号与 Key 不互通": "; workflow phải chạy thành công trên giao diện web trước, với {{PROMPT}} và các placeholder khác được ghi vào ô nhập của node tương ứng (quy ước giống workflow cục bộ); sau đó dán ID workflow hoặc liên kết trang vào “Thêm workflow” để xác thực; tài khoản và Key của trang Trung Quốc và trang quốc tế không dùng chung được",
