"待提交问题:Agent 运行中发现系统代码缺陷或需要新增功能时自动整理成 issue,点击查看并提交给开发者,让你的客户端运行得更好": "Vấn đề chờ gửi: khi agent phát hiện lỗi trong mã ứng dụng hoặc tính năng cần bổ sung trong lúc chạy, nó tự động soạn thành issue; bấm để xem và gửi cho nhà phát triển để ứng dụng của bạn chạy tốt hơn",
"Agent 运行中确认问题属于系统代码缺陷、或需要系统新增功能时,自动整理成 issue 列在下方,点「提交」即打开预填好的 GitHub 页面由你确认提交。": "Khi agent xác nhận trong lúc chạy rằng vấn đề là lỗi của mã ứng dụng, hoặc ứng dụng cần tính năng mới, nó tự động soạn thành issue và liệt kê bên dưới; bấm \"Gửi\" sẽ mở trang GitHub đã điền sẵn để bạn xác nhận.",
"问题只写机制,内容已脱敏(路径、项目名、密钥),不含剧情、提示词与项目内容。": "Issue chỉ mô tả cơ chế; nội dung đã được ẩn danh (đường dẫn, tên dự án, khóa) và không chứa cốt truyện, prompt hay nội dung dự án.",
