"虚拟人像资产库 — Agentics：VideoAgents": "Thư viện chân dung ảo — Agentics: VideoAgents",
"火山方舟私域虚拟人像素材库:人物形象图入库后,生成视频时自动以资产 URI 提交,规避人脸参考图审核拦截": "Thư viện tài sản chân dung ảo riêng của Volcano Ark: sau khi đưa ảnh nhân vật vào kho, khi tạo video sẽ tự động gửi bằng URI tài sản, tránh bị chặn kiểm duyệt ảnh tham chiếu khuôn mặt",
"🧑‍🎨 虚拟人像资产库": "🧑‍🎨 Thư viện chân dung ảo",
"火山方舟私域素材库:入库的人物形象图在生成视频时以资产 URI 提交,规避人脸参考图审核拦截": "Thư viện tài sản riêng Volcano Ark: ảnh nhân vật đã vào kho sẽ được gửi bằng URI tài sản khi tạo video, tránh chặn kiểm duyệt ảnh tham chiếu khuôn mặt",
"📋 使用前准备": "📋 Chuẩn bị trước khi dùng",
"在火山方舟开通": "Kích hoạt trên Volcano Ark gói",
"高级创作权益包": "Quyền lợi sáng tạo nâng cao",
"(私域虚拟人像素材库的前置条件)。": "(điều kiện tiên quyết của thư viện chân dung ảo riêng).",
"在火山引擎控制台": "Trong bảng điều khiển Volcano Engine, mở",
"API 访问密钥管理": "Quản lý khóa truy cập API",
"创建并获取 Access Key / Secret Key(IAM 密钥,非 ark- 开头的方舟 API Key),填入下方并保存。": "tạo và lấy Access Key / Secret Key (khóa IAM, không phải Ark API Key bắt đầu bằng ark-), điền vào bên dưới rồi lưu.",
"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "Sau khi bấm 「Bật」, quản lý tài sản đã vào kho ở bên dưới; mỗi ảnh trên trang Xem trước nhân vật sẽ có nút 「Vào kho」, khi tạo lại nhóm, ảnh tham chiếu đã vào kho (Active) sẽ tự động gửi bằng URI tài sản (asset://ID).",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "Lưu ý: vào kho được kiểm duyệt bất đồng bộ (Processing → Active/Failed); chỉ tài sản Active mới dùng được để tạo video. Tài sản được cách ly theo「dự án」Ark — ProjectName bên dưới phải trùng với dự án của Ark API Key dùng tạo video ở trang「Mô hình tạo」(mặc định default).",
"🔑 密钥与开关": "🔑 Khóa & công tắc",
"Access Key / Secret Key 留空时,自动使用「⚙️ 设置 → 文件托管 → 火山引擎 TOS」已配置的 AK/SK(或环境变量 TOS_ACCESS_KEY/TOS_SECRET_KEY)。": "Nếu để trống Access Key / Secret Key, hệ thống tự dùng AK/SK đã cấu hình ở ⚙️ Cài đặt → Lưu trữ tệp → Volcano TOS (hoặc biến môi trường TOS_ACCESS_KEY/TOS_SECRET_KEY).",
"default(须与视频生成 API Key 所属项目一致)": "default (phải trùng dự án của API Key tạo video)",
