"本 Agent 的技能:点击查看已安装清单,选择一项即把技能路径(如 skills/sd25-pe)插入输入框;「加载技能」可上传技能 zip 包或单个 SKILL.md 安装到本 Agent": "Kỹ năng của agent này: nhấp để xem danh sách đã cài; chọn một để chèn đường dẫn của nó (vd. skills/sd25-pe) vào ô nhập; \"Tải kỹ năng\" tải lên gói zip kỹ năng hoặc một tệp SKILL.md duy nhất để cài vào agent này",
"点击一项技能,把它的路径(如 skills/sd25-pe)插入输入框,然后在指令里说明要用该技能做什么。「加载技能」可上传技能 zip 包(内含 SKILL.md)或直接上传单个 SKILL.md(目录名取 frontmatter 的 name 或文件名),安装到本 Agent 的 skills/ 目录。": "Nhấp vào một kỹ năng để chèn đường dẫn của nó (vd. skills/sd25-pe) vào ô nhập, rồi nêu trong chỉ dẫn muốn dùng kỹ năng đó làm gì. \"Tải kỹ năng\" tải lên gói zip (chứa SKILL.md) hoặc một tệp SKILL.md duy nhất (tên thư mục lấy từ name trong frontmatter hoặc tên tệp) và cài vào thư mục skills/ của agent này.",
