"视频提示词技能:Prompt 工程师写组级视频提示词时必须套用的官方提示词技能。自动=按真正跑视频生成的模型解析(Seedance 2.5→sd25-pe,Seedance 2.0 系列→sd20-pe,MiniMax H3→h3-pe,Wan 3.0→wan3-pe);解析不到时可手选或跳过。H3A 分镜签字时会再次确认并冻结": "Kỹ năng prompt video: kỹ năng viết prompt chính thức mà Kỹ sư prompt bắt buộc áp dụng khi viết prompt video theo nhóm. Tự động = xác định theo mô hình thực sự chạy tạo video (Seedance 2.5→sd25-pe, dòng Seedance 2.0→sd20-pe, MiniMax H3→h3-pe, Wan 3.0→wan3-pe); không khớp thì chọn thủ công hoặc bỏ qua. Được xác nhận lại và khóa khi ký duyệt storyboard H3A",
