"Fal 图像生成 API(queue.fal.run 异步队列,托管 Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image 等端点);模型 ID 填家族前缀,无参考图走文生图端点、有参考图自动切 edit 端点,「自定义…」也可填完整端点 ID;尺寸/参考图上限/seed 按模型映射;Key 与视频段 Fal 共用(任一处填写即可),在": "API sinh ảnh Fal (hàng đợi bất đồng bộ queue.fal.run, host các endpoint Seedream, Nano Banana, GPT Image, FLUX.2, Qwen Image…); ID mô hình là tiền tố họ mô hình: không có tham chiếu thì dùng endpoint văn bản sang ảnh, có tham chiếu thì tự chuyển sang endpoint edit; \"Tùy chỉnh…\" cũng nhận ID endpoint đầy đủ; kích thước / giới hạn tham chiếu / seed ánh xạ theo mô hình; Key dùng chung với tab Video → Fal (chỉ cần điền một nơi), tạo tại",
