"Kling 3.0 Standard(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Standard (host trên Fal; khung đầu/cuối, 3–15 s, âm thanh gốc, không hỗ trợ tài liệu tham chiếu)",
