"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "Cách phát: phát các đoạn đã tạo theo thứ tự; khi đoạn mới chưa tới thì phát lại đoạn mới nhất, tới rồi thì nối sau đoạn hiện tại mà không ngắt. Tạo thường chậm hơn phát nên phát lại là bình thường — tăng độ dài đoạn để giảm tỷ lệ phát lại. Khi số đoạn chờ đạt giới hạn (mặc định 3, chỉnh trong Tùy chọn nâng cao), tạm dừng tạo; phát xong một đoạn thì tiếp tục. Sau khi dừng, lặp lại toàn bộ đoạn.",
