"⚠ 参考视频 [Video {n}] 由流水线注入({kind}),不是手动添加的:\n{ref}\n\n删除后 prompt 正文中的 [Video N] 引用会自动重排,指向该视频的引用与其固定说明段会被移除;流水线重跑同步脚本时会按模型预算重新挂回(要彻底不用请换模型或关闭对应项目开关)。重出本组生效。\n\n确定删除?": "⚠ Video tham chiếu [Video {n}] do pipeline chèn ({kind}), không phải thêm thủ công:\n{ref}\n\nSau khi xóa, các dẫn chiếu [Video N] trong prompt sẽ tự đánh số lại; dẫn chiếu tới video này và đoạn giải thích cố định của nó bị gỡ. Chạy lại script đồng bộ sẽ gắn lại trong ngân sách mô hình (muốn bỏ hẳn hãy đổi mô hình hoặc tắt tùy chọn dự án tương ứng). Có hiệu lực khi tạo lại nhóm.\n\nXóa?",
"确认移除这个参考视频 [Video {n}]?\n{ref}\n(本地上传的文件将一并删除;移除后随本组重出生效)": "Xóa video tham chiếu [Video {n}]?\n{ref}\n(tệp đã tải lên cũng bị xóa; có hiệu lực khi tạo lại nhóm)",
"✅ 已删除参考视频": "✅ Đã xóa video tham chiếu",
"文件超过 45MB(方舟参考视频单文件上限),请先压缩": "Tệp vượt 45MB (giới hạn mỗi video tham chiếu của Ark); hãy nén trước",
"✅ 已上传并加入参考视频 [Video {n}];重出本组 prompt 时须补写该编号的说明句": "✅ Đã tải lên và thêm làm [Video {n}]; bổ sung câu cho số này khi tạo lại prompt của nhóm",
"{n} 个参考视频": "{n} video tham chiếu",
"⚠ {reason}:点「🎬 视频」删除参考视频,或点「🎛 模型」给本组单独换参考视频上限更高的视频模型;处理后重出本组": "⚠ {reason}: bấm “🎬 Video” để xóa video tham chiếu, hoặc “🎛 Mô hình” để đổi riêng cho nhóm này sang mô hình có giới hạn cao hơn; sau đó tạo lại nhóm",
"查看场景模型 / 调度计划 / 预览文件 / 参考视频的文件状态": "Xem trạng thái tệp: mô hình cảnh / kế hoạch dàn cảnh / tệp xem trước / video tham chiếu",
