// 「3D 白模」板块的「创建全景图」(2026-10-05):按白模旋转视角当前的相机位置与朝向出一张,弹窗确认后才创建
"按白模旋转视角当前的摄像机位置(x / y / z)与朝向(yaw)出一张 2:1 全景(只出这一张,其它锚点不动;消耗全景模型出图费用)": "Tạo một ảnh toàn cảnh 2:1 từ vị trí camera hiện tại (x / y / z) và hướng nhìn (yaw) của góc nhìn xoay trên mô hình khối (chỉ tạo ảnh này; các điểm neo khác giữ nguyên; tốn phí tạo ảnh của mô hình toàn cảnh)",
