"相机脚下平面的海拔,0 = 地面;相机高度 = y + 眼高。点位后按该处高度自动填,可再改": "Cao độ của mặt phẳng camera đứng; 0 = mặt đất. Chiều cao camera = y + tầm mắt. Tự điền theo độ cao tại vị trí đã chọn; có thể sửa",
