"开启后控制台输入框与预览页「修改」浮窗的右侧出现麦克风按钮:点一下开始录音、再点一下结束,录音由本机 faster-whisper 模型转成文字插到光标处(最长 60 秒,音频不出本机,不需要任何 API Key)。识别语言跟随界面语言。模型首次使用需先下载,越大的模型越准但越慢:small 起步够用,Apple 芯片可选 medium 或 large-v3-turbo。": "Khi bật, nút micrô xuất hiện ở bên phải ô nhập của bảng điều khiển và cửa sổ 'Sửa' ở trang xem trước: nhấn một lần để bắt đầu ghi, nhấn lại để dừng; bản ghi được mô hình faster-whisper cục bộ chuyển thành văn bản và chèn tại vị trí con trỏ (tối đa 60 giây, âm thanh không rời khỏi máy, không cần API key). Ngôn ngữ nhận dạng theo ngôn ngữ giao diện. Cần tải mô hình trước lần dùng đầu; mô hình càng lớn càng chính xác nhưng chậm hơn: small là đủ để bắt đầu, chip Apple có thể chọn medium hoặc large-v3-turbo.",
