"提交本集 ({n})": "Gửi tập này ({n})",
"一次性提交本集所有待提交内容(待提交注释 + 已裁决待决项 + 3D 直改),按工位拆批派单;同组有批次运行中会被拒": "Gửi một lần tất cả mục chờ gửi của tập này (ghi chú nháp + mục chờ quyết đã chọn + chỉnh sửa 3D trực tiếp), chia lô theo trạm; bị từ chối nếu cùng nhóm đang có lô chạy",
"提交全集所有待提交内容;切到「本组」只提交当前组": "Gửi mọi mục chờ gửi của cả tập; chuyển sang «Nhóm này» để chỉ gửi nhóm hiện tại",
"只提交当前组;切到「全集」一次提交所有组的待提交内容": "Chỉ gửi nhóm hiện tại; chuyển sang «Cả tập» để gửi một lần mọi mục chờ gửi của tất cả nhóm",
"提交本组 ({n})": "Gửi nhóm này ({n})",
"本组建模依据与检查 ({n})": "Căn cứ dựng mô hình và kiểm tra của nhóm này ({n})",
"待提交 {n}": "Chờ gửi {n}",
"待答 {n}": "Chờ trả lời {n}",
"已选 {n},提交时套用": "Đã chọn {n}, áp dụng khi gửi",
"提交 = 一次派单给白模调度 Agent = 一个新版本": "Gửi = một lần giao việc cho Agent dàn cảnh mô hình khối = một phiên bản mới",
"点对象 = 选中并写注释;摄影机在俯视/旋转视角里可点": "Nhấn đối tượng = chọn và viết chú thích; máy quay có thể nhấn trong góc nhìn từ trên/xoay",
"版本 = 该组编译结果快照;A|B 实时渲染比对": "Phiên bản = ảnh chụp kết quả biên dịch của nhóm; A|B so sánh bằng kết xuất thời gian thực",
"已派单给白模调度 Agent(批次 {b},运行 {r});完成后自动加载新版本": "Đã giao việc cho Agent dàn cảnh mô hình khối (lô {b}, lượt chạy {r}); phiên bản mới sẽ tự tải khi hoàn thành",
"已存为 v{v}": "Đã lưu thành v{v}",
"同场次在场,本组白模未出现": "Có mặt trong cùng phân cảnh nhưng không xuất hiện trong whitebox của nhóm này",
"本组有批次运行中,等回收后再提交": "Nhóm này có lô đang chạy, hãy gửi lại sau khi thu hồi",
"项目未开启「人物精确空间位置」,白模链未启用": "Dự án chưa bật «Vị trí không gian chính xác của nhân vật», chuỗi whitebox chưa được kích hoạt",
"已提交,等 Agent 处理": "Đã gửi, chờ Agent xử lý",
"还没有版本;首次提交会自动存一份基线": "Chưa có phiên bản nào; lần gửi đầu tiên sẽ tự lưu một đường cơ sở",
"点组切换;黄点 = 有待提交注释": "Nhấn nhóm để chuyển; chấm vàng = có chú thích chờ gửi",
"存版失败:": "Lưu phiên bản thất bại:",
"派单失败:": "Giao việc thất bại:",
"版本加载失败:": "Tải phiên bản thất bại:",
"默认取舍:": "Phương án mặc định:",
"例:何香在 3 秒时往北挪 1 米,面向王三合;机位降到 1.2 m 平视": "Ví dụ: Hà Hương ở giây thứ 3 dịch lên phía bắc 1 m, quay mặt về Vương Tam Hợp; hạ máy quay xuống 1,2 m ngang tầm mắt",
"还没有注释:点 3D 里的对象或下方对象卡,写下修改要求": "Chưa có chú thích: nhấn đối tượng trong 3D hoặc thẻ đối tượng bên dưới và viết yêu cầu sửa đổi",
"导演台:在 3D 白模现场按分镜组逐对象写修改注释,批量提交给白模调度 Agent,按版本 A|B 比对": "Bàn đạo diễn: tại hiện trường whitebox 3D, viết chú thích sửa đổi cho từng đối tượng theo nhóm cảnh quay, gửi hàng loạt cho Agent dàn cảnh mô hình khối và so sánh các phiên bản A|B",
"到导演台:大视窗看白模,逐对象写修改注释,批量提交并按版本 A|B 比对": "Tới bàn đạo diễn: xem whitebox trên khung nhìn lớn, viết chú thích sửa đổi cho từng đối tượng, gửi hàng loạt và so sánh các phiên bản A|B",
"本组没有待决项(白模调度 Agent 没有拿不准的取舍)": "Nhóm này không có mục chờ quyết định (Agent dàn cảnh mô hình khối không có lựa chọn nào chưa chắc chắn)",
