"四联监看:白模机位 / 故事板草图 / 分镜背景图 / 已生成成片,同一时间轴同步": "Màn hình 4 khung: camera whitebox / phác thảo storyboard / nền cảnh quay / video đã tạo, đồng bộ trên cùng một dòng thời gian",
"取景辅助线:三分线 / 中心十字 / 动作安全框(摄像机视角)": "Đường gióng khung hình: đường 1/3 / chữ thập trung tâm / khung an toàn hành động (góc nhìn camera)",
