// 分镜剪辑·插黑 / 定格(2026-09-17)
"插黑 / 定格": "Đen / đóng băng",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片时外挂声轨/字幕按时间映射表自动同步)": "Xóa hẳn các đoạn đã đánh dấu và nối phần còn lại theo thứ tự thành phiên bản mới của nhóm này (thời lượng ngắn lại; khi hoàn thiện, âm thanh ngoài và phụ đề được đồng bộ lại qua bản đồ thời gian)",
"控制切换节奏:在当前时刻插入「前一帧定格 + 黑场」生成本组新版本;或放在本组开头 / 结尾的组边界,写成组间转场调整(提交即回写 shot_list,出成片时插帧)。成片按插入量变长,外挂声轨与字幕按同一张时间映射表自动平移;黑场声音可延续前段、淡出或静音": "Điều khiển nhịp: chèn \"đóng băng khung hình trước + đen\" tại đầu phát để tạo phiên bản mới, hoặc đặt ở ranh giới đầu / cuối nhóm này như một điều chỉnh chuyển cảnh giữa các nhóm (gửi sẽ ghi vào shot_list; khung hình được chèn khi hoàn thiện). Tập dài thêm đúng phần chèn; âm thanh ngoài và phụ đề dịch theo cùng một bản đồ thời gian; âm thanh dưới màn đen có thể kéo dài, mờ dần hoặc tắt",
"分镜剪辑,四个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 插黑 / 定格——在当前时刻或组边界插入定格帧 + 黑场控制切换节奏;④ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "Biên tập cảnh, bốn mô-đun: ① Xóa — bỏ các đoạn đã đánh dấu, phần còn lại thành phiên bản mới; ② Thay — đổi các đoạn đã cắt bằng cùng đoạn của phiên bản khác; ③ Đen / đóng băng — chèn khung hình đóng băng + đen tại đầu phát hoặc ranh giới nhóm để điều khiển nhịp; ④ Gửi cho người dựng — gửi chỉ dẫn cho agent dựng phim, kết quả được đăng ký thành phiên bản mới",
"+{s}s → {r}s": "+{s}s → {r}s",
