"{a} → {b} 的组边界:本组尾定格 / 黑场后进入下组(写入下组的组间转场调整)": "Ranh giới {a} → {b}: đóng băng khung cuối của nhóm này / đen, rồi vào nhóm sau (ghi vào điều chỉnh chuyển cảnh của nhóm sau)",
