"柔化(高频软化)": "Làm mềm (làm dịu tần số cao)",
"半径(1080p 基准 px)": "Bán kính (px ở 1080p)",
"高斯模糊与原片按强度混合,压掉高频细节而不糊轮廓(回忆/梦境段的柔焦感);半径随画面高度等比缩放": "Trộn làm mờ Gaussian với bản gốc theo cường độ, bỏ chi tiết nhỏ mà không nhòe đường nét (cảm giác nét mềm cho đoạn hồi tưởng / giấc mơ); bán kính tỉ lệ theo chiều cao khung hình",
"全部集": "Tất cả tập",
"按集过滤:只显示该集出现的资产": "Lọc theo tập: chỉ hiển thị tài sản xuất hiện trong tập đó",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度、白模自检、Debug 模式": "Cài đặt nâng cao cho agent: hạn mức chạy song song của agent fan-out, thời gian chờ chạy / không có đầu ra, hạn mức bộ nhớ hội thoại giữa các lượt, giới hạn số lần tự chạy lại, thời gian chờ xác nhận chạy lại, độ sâu suy nghĩ, tự kiểm whitebox, chế độ Debug",
"白模自检": "Tự kiểm whitebox",
"显示 SOUL.md 等开发者入口": "Hiển thị lối vào dành cho nhà phát triển như SOUL.md",
"白模调度编译后出静帧自检取景": "Xuất khung hình tĩnh sau khi biên dịch whitebox để tự kiểm bố cục",
"默认勾选:白模调度 Agent 每次新建或修改分镜白模、编译通过后,用宿主命令 render_whitebox.py --stills 对本单改动过的组做无头渲染——每镜取首/中/尾等时刻的摄影机视角加一张空间视角,拼成每组一张联系表(项目 directing 下该集的 whitebox/stills 目录),Agent 读图核对主体是否在画内、有无被墙或道具遮挡、正面/背影与调度是否一致、景别是否相符,有问题先自行修正或开待决项,再交你在预览页审看签字。渲染全在本机完成,不调用任何生成模型、不产生费用,也不导出 camera.mp4(导出仍须 H3W 签字);每组约多花十几秒与一次读图的 token。取消勾选则只做数值自检与宿主机检,不出静帧。全局设置,通过运行提示词注入白模调度 Agent,保存后对后续启动的工单生效。": "Mặc định bật: mỗi khi Agent dàn dựng whitebox tạo mới hoặc sửa whitebox phân cảnh và biên dịch thành công, nó chạy lệnh máy chủ render_whitebox.py --stills cho các nhóm đã thay đổi trong phiếu việc đó. Việc kết xuất chạy không giao diện: mỗi cảnh quay lấy góc máy quay tại đầu / giữa / cuối (và các thời điểm chính) cùng một góc nhìn không gian, ghép thành một bảng liên hệ cho mỗi nhóm (trong thư mục whitebox/stills của tập đó dưới directing của dự án). Agent đọc ảnh để kiểm tra chủ thể có trong khung hình không, có bị tường hay đạo cụ che không, mặt trước / sau lưng có khớp dàn dựng không, cỡ cảnh có phù hợp không; nếu có vấn đề thì tự sửa hoặc mở mục chờ quyết định trước khi giao cho bạn duyệt và ký ở trang xem trước. Kết xuất hoàn toàn trên máy: không gọi mô hình tạo sinh, không tốn phí, không xuất camera.mp4 (xuất vẫn cần chữ ký H3W); mỗi nhóm tốn thêm khoảng mười mấy giây và token của một lần đọc ảnh. Bỏ chọn thì chỉ tự kiểm số liệu và kiểm tra của máy chủ, không xuất khung tĩnh. Thiết lập toàn cục, được chèn vào Agent dàn dựng whitebox qua prompt chạy; có hiệu lực với các phiếu việc bắt đầu sau khi lưu.",
"本组尚未白模调度，当前没有可审看的白模。": "Nhóm này chưa được dàn dựng whitebox; hiện chưa có whitebox để duyệt.",
"白模调度 Agent 完成本集工单后这里会显示正式白模；在此之前无需对白模提修改意见。": "Whitebox chính thức sẽ hiển thị ở đây sau khi Agent dàn dựng whitebox hoàn thành phiếu việc của tập này; trước đó không cần gửi ý kiến chỉnh sửa whitebox.",
"系统按分镜与动线自动推断的粗略白模，机位、走位、朝向多为估计值，不是白模调度的交付物": "Whitebox thô do hệ thống tự suy ra từ storyboard và blocking; vị trí máy quay, di chuyển và hướng mặt phần lớn là ước lượng, không phải sản phẩm của khâu dàn dựng whitebox",
"查看自动推断草稿（仅供参考，不接受修改）": "Xem bản nháp tự suy luận (chỉ để tham khảo, không nhận chỉnh sửa)",
"自动推断草稿": "Bản nháp tự suy luận",
"自动推断草稿：本组未经白模调度，以下画面由系统按分镜与动线粗略推断，仅供参考；修改入口在白模调度完成后开放。": "Bản nháp tự suy luận: nhóm này chưa qua dàn dựng whitebox. Hình bên dưới do hệ thống suy ra sơ bộ từ storyboard và blocking, chỉ để tham khảo; lối chỉnh sửa sẽ mở sau khi dàn dựng whitebox hoàn tất.",
"本组尚未白模调度,当前是系统自动推断的草稿,只能查看;白模调度完成后再提修改": "Nhóm này chưa được dàn dựng whitebox; nội dung đang hiển thị là bản nháp tự suy luận, chỉ xem được. Hãy gửi chỉnh sửa sau khi dàn dựng whitebox hoàn tất",
"未调度": "Chưa dàn dựng",
"缺陷单": "Phiếu lỗi",
"缺陷单:本项目 qa/defects/ 审核问题反馈,可逐条发给总制片处理": "Phiếu lỗi: phản hồi vấn đề kiểm duyệt qa/defects/ của dự án này; gửi từng phiếu cho Giám đốc sản xuất xử lý",
"成片发布:每集成片 final 视频 + 封面 thumbnail + 发布物料": "Bản hoàn chỉnh & phát hành: Video final mỗi tập + ảnh bìa thumbnail + tài liệu phát hành",
