"右下角弹出消息窗,把这张缺陷单发给总制片处理": "Mở cửa sổ tin nhắn ở góc dưới bên phải để gửi phiếu lỗi này cho Giám đốc sản xuất",
"全部分集": "Tất cả các tập",
"只看未关闭": "Chỉ chưa đóng",
