"分镜背景图 {ep}/{sid}({role};文件 {file};库 key {key};修订命令 python code/revise_shot_plate.py --project {proj} --ep {ep} --shot {sid} --role {r} --change \"<英文修改要求>\":以当前图为参考按意见新出一张并替换本镜该背景图,原图不动)": "Nền cảnh quay {ep}/{sid} ({role}; tệp {file}; khóa thư viện {key}; lệnh sửa python code/revise_shot_plate.py --project {proj} --ep {ep} --shot {sid} --role {r} --change \"<yêu cầu sửa bằng tiếng Anh>\": tạo một ảnh mới từ ảnh hiện tại theo góp ý và thay cho nền của cảnh này; ảnh gốc giữ nguyên)",
