"0–51,越小画质越高体积越大;18 ≈ 视觉无损": "0–51, càng nhỏ chất lượng càng cao và file càng lớn; 18 ≈ gần như không mất chất lượng",
"编码预设": "Preset mã hóa",
"slow(默认)": "slow (mặc định)",
"内置非 AI 插值放大:ffmpeg scale 滤镜 + libx264 重编码,音轨流拷贝,fps/时长/画幅不变。不生成新细节,只是像素变多;不花生成费,适合只需过发布规格的项目。目标尺寸由「输出设置」成片分辨率 × 画幅自动换算。": "Phóng nội suy không AI tích hợp: bộ lọc ffmpeg scale + mã hóa lại libx264, âm thanh sao chép luồng, fps/thời lượng/tỷ lệ không đổi. Không tạo chi tiết mới, chỉ tăng số điểm ảnh; không tốn phí sinh, hợp với dự án chỉ cần đạt quy cách phát hành. Kích thước đích tính tự động từ độ phân giải phát hành × tỷ lệ trong Cài đặt đầu ra.",
"Seedance 2.5 样片(Draft)模式:选中即激活,无需另填 Key 或模型,凭证与模型沿用视频生成的火山引擎标签页。": "Chế độ nháp (Draft) Seedance 2.5: chọn tab là kích hoạt, không cần thêm Key hay mô hình; thông tin xác thực và mô hình lấy từ tab Volcano Engine của phần sinh video.",
"激活条件:视频生效渠道为火山引擎(或 BytePlus,方舟同一 API)且模型为 Seedance 2.5;项目「输出设置」草稿分辨率 = 480p、成片分辨率 = 1080p(官方:样片仅 480p,出原片仅 1080p)。不满足时视频照常按普通模式生成,并在日志提示。": "Điều kiện kích hoạt: nhà cung cấp video hiệu lực là Volcano Engine (hoặc BytePlus, cùng API Ark) với mô hình Seedance 2.5; Cài đặt đầu ra của dự án có độ phân giải nháp 480p và phát hành 1080p (chính thức: nháp chỉ 480p, bản chính chỉ 1080p). Không thỏa thì video sinh bình thường và ghi trong log.",
"工作方式:① 生成阶段自动带 draft=true 出 480p 样片(token 用量与普通 480p 一致),Draft 任务 ID 写进组 clip 同名 meta.json 的 draft_task 段;② 超分阶段 genmedia.py upscale 按该 ID 让方舟复用同一提示词/素材/时长/画幅/seed/音频设置生成 1080p 原片(正常推理计费),画面关键要素与过审样片一致;③ Draft 任务 ID 自创建起 7 天有效,过期只能重出样片。": "Cách hoạt động: ① khi sinh, gửi kèm draft=true để ra bản nháp 480p (token như 480p thường), ID tác vụ Draft ghi vào mục draft_task trong meta.json của clip nhóm; ② khi nâng độ phân giải, genmedia.py upscale dùng ID đó để Ark tái sử dụng cùng prompt/tư liệu/thời lượng/tỷ lệ/seed/âm thanh sinh bản chính 1080p (tính phí suy luận bình thường), các yếu tố chính khớp bản nháp đã duyệt; ③ ID Draft có hiệu lực 7 ngày kể từ khi tạo, hết hạn phải sinh lại nháp.",
"适用条件(源 clip 必须是 MiniMax-H3 768P 直出规格):含音轨;24 fps;宽高均能被 32 整除;面积 ≤ 768×1344;107–362 帧(约 4–15 秒)。": "Điều kiện áp dụng (clip nguồn phải là đầu ra gốc MiniMax-H3 768P): có âm thanh; 24 fps; rộng và cao chia hết cho 32; diện tích ≤ 768×1344; 107–362 khung hình (khoảng 4–15 giây).",
"云端超分工作流": "Workflow nâng độ phân giải trên đám mây",
"超分工作流 API": "API workflow nâng độ phân giải",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(comfy/scale-* 模板;SeedVR2 节点 ComfyUI 官方内置,云端可用);长片 1080p 以上在云端可能显存不足,以任务结果为准": "(cần gói Comfy Cloud, dùng chung hạn mức tháng với bản web; gói miễn phí không có quyền API); danh sách workflow giống bản cục bộ (mẫu comfy/scale-*; nút SeedVR2 tích hợp sẵn trong ComfyUI chính thức, dùng được trên đám mây); clip dài từ 1080p trở lên có thể thiếu VRAM trên đám mây, căn cứ kết quả tác vụ",
"获取;请先在工作区跑通 SeedVR2 类超分工作流,再把工作流 ID 或页面链接粘贴到「添加工作流」验证;无占位符的普通导出件系统会直绑唯一的源视频加载节点(LoadVideo 系)+ SeedVR2Preprocess 上游的缩放节点(目标边长/宽高)+ 采样器种子,也兼容 VIDEO/WIDTH/HEIGHT/SEED 占位符;这里的工作流收藏与视频生成板块各自独立;国内站与国际站账号与 Key 不互通": "; hãy chạy thử workflow nâng độ phân giải kiểu SeedVR2 trong workspace trước, rồi dán ID workflow hoặc link trang vào “Thêm workflow” để xác minh; bản xuất thường không có placeholder sẽ được hệ thống gắn trực tiếp nút tải video nguồn duy nhất (họ LoadVideo) + nút đổi kích thước phía trước SeedVR2Preprocess (cạnh đích / rộng cao) + seed của sampler, cũng hỗ trợ placeholder VIDEO/WIDTH/HEIGHT/SEED; danh sách yêu thích ở đây độc lập với thẻ sinh video; tài khoản và Key của .cn và .ai không dùng chung",
"🧩 组 clip 与超分方法": "🧩 Clip nhóm và phương pháp nâng độ phân giải",
