// 集尾收束(2026-09-25):视频节奏弹窗「集尾收束」行 + 分镜预览页过场汇总条集尾行
"集尾收束": "Kết tập",
"切黑(突然黑屏)": "Cắt sang đen (tối đột ngột)",
