"停留": "giữ",
"集尾": "Cuối tập",
"本集覆盖": "ghi đè cho tập này",
"按下方「集尾收束」": "xem “Kết tập” bên dưới",
"集尾淡出时长需在 0.3–3 秒之间": "Thời lượng mờ dần kết tập phải 0,3–3 s",
"集尾停留需在 0–3 秒之间": "Thời gian giữ kết tập phải 0–3 s",
"切黑须停留 >0 秒(否则等于停在末帧)": "Cắt sang đen cần giữ > 0 s (nếu không chỉ dừng ở khung cuối)",
"正片结尾的收束:最后一组尾部淡出到黑/白后停留,或直接切黑(突然黑屏,悬念感;声音默认同刻切断);外挂声轨同刻淡出/切断,片尾包装接在停留之后。出成片时由 render_transitions 落地;某一集要不同处理可在分镜预览页过场汇总条单独设。": "Cách kết thúc tập: nhóm cuối mờ dần sang đen/trắng rồi giữ, hoặc cắt thẳng sang đen (tối đột ngột tạo hồi hộp; âm thanh mặc định cắt cùng lúc); track âm thanh ngoài mờ dần/cắt cùng thời điểm và phần outro nối sau đoạn giữ. Do render_transitions áp dụng khi xuất bản cuối; muốn tập nào khác đi thì đặt riêng ở thanh tóm tắt chuyển cảnh trên trang storyboard.",
"正片结尾的收束:最后一组尾部淡出/切黑后停留,外挂声轨同刻淡出或切断;片尾包装接在停留之后": "Cách kết thúc tập: nhóm cuối mờ dần/cắt sang đen rồi giữ; âm thanh ngoài mờ dần hoặc cắt cùng thời điểm; outro nối sau đoạn giữ",
"本集集尾收束(集级覆盖,项目默认在「视频节奏」设置);改后出成片时落地,已有成片须重跑转场": "Kết tập của tập này (ghi đè theo tập; mặc định dự án ở “Nhịp video”); áp dụng khi xuất bản cuối, bản dựng đã có phải chạy lại chuyển cảnh",
"渲染集尾预览小片:末组尾 2s + 收束,与成片同一滤镜链": "Dựng bản xem trước kết tập: 2 s cuối của nhóm cuối + kết tập, cùng chuỗi bộ lọc với bản dựng cuối",
// NSFW 模式(设置→高级;index.html 弹窗 + preview_storyboard.html 组卡 🔞)
"NSFW 模式": "Chế độ NSFW",
"NSFW 模式:默认关;开启后可为语言/图像/视频分别指定备用模型,标记 NSFW 的工单与分镜组自动改走备用模型,主渠道内容审核拒收时自动切换重提一次": "Chế độ NSFW: mặc định tắt; khi bật có thể chỉ định mô hình dự phòng riêng cho ngôn ngữ/hình ảnh/video, phiếu và nhóm được gắn cờ NSFW tự động chuyển sang mô hình dự phòng, và khi kênh chính từ chối vì kiểm duyệt nội dung sẽ tự chuyển và gửi lại một lần",
"🔞 NSFW 模式": "🔞 Chế độ NSFW",
"启用 NSFW 模式": "Bật chế độ NSFW",
"默认关。开启后可分别指定三类「备用模型」;派单与出图/出片按三层路由决定何时改用备用模型:① 显式标记优先——工单带 nsfw: true(总制片按剧本拆解表事件 content_flags → 分镜组 nsfw 推导,或你在分镜预览组卡点 🔞 手动标记)首次派单即走备用模型;② 兜底——主渠道返回内容审核拒收时,genmedia 同一调用内改备用渠道重提一次(不计重跑次数)并把该组记为 NSFW,后续不再先撞主模型;语言模型被拒不做进程内切换,同一 task_id 重派时改用备用语言模型。本模式只决定用哪套模型,不放宽内容安全审核与平台分级。": "Mặc định tắt. Khi bật, có thể chỉ định riêng ba loại “mô hình dự phòng”; giao việc và tạo ảnh/video quyết định khi nào dùng mô hình dự phòng theo ba tầng: ① Ưu tiên cờ tường minh — phiếu mang nsfw: true (Nhà sản xuất suy ra nsfw của nhóm từ content_flags của sự kiện trong bảng phân tích kịch bản, hoặc bạn gắn cờ thủ công bằng 🔞 trên thẻ nhóm ở trang xem trước storyboard) đi thẳng mô hình dự phòng ngay lần giao đầu; ② Dự phòng — khi kênh chính trả về từ chối kiểm duyệt nội dung, genmedia chuyển sang kênh dự phòng và gửi lại một lần trong cùng lời gọi (không tính vào số lần chạy lại), đồng thời ghi nhóm đó là NSFW để về sau không thử mô hình chính trước nữa; mô hình ngôn ngữ bị từ chối không chuyển trong tiến trình, khi giao lại cùng task_id sẽ dùng mô hình ngôn ngữ dự phòng. Chế độ này chỉ quyết định dùng bộ mô hình nào, không nới lỏng kiểm duyệt an toàn nội dung hay phân loại của nền tảng.",
"图像模型": "Mô hình hình ảnh",
"渠道须已在「🎨 生成模型」页配好 Key(未配置的置灰);留「不设置」= 该类不切换,照常走主模型。ComfyUI 的二级选项是运行方式。备用渠道不可用时不会偷跑主模型,而是报错交你裁决。": "Kênh phải đã cấu hình Key ở trang “🎨 Mô hình tạo sinh” (kênh chưa cấu hình bị làm mờ); để “Không đặt” = loại đó không chuyển, vẫn dùng mô hình chính như thường. Với ComfyUI, tùy chọn cấp hai là chế độ chạy. Khi kênh dự phòng không khả dụng sẽ không âm thầm chạy mô hình chính mà báo lỗi để bạn quyết định.",
"审核拒收后自动切换": "Tự chuyển sau khi bị từ chối kiểm duyệt",
"关闭后只按显式标记路由,主渠道审核拒收照常报错": "Khi tắt, chỉ định tuyến theo cờ tường minh; kênh chính bị từ chối kiểm duyệt vẫn báo lỗi như thường",
