"已认领 {anchor}/{scheme} → {file};当前判据:投影 {p} / 白模一致性 {c}": "Đã chấp nhận {anchor}/{scheme} → {file}; kiểm tra hiện tại: phép chiếu {p} / khớp whitebox {c}",
