"弃用中…": "Đang loại bỏ…",
"服务未重启:弃用接口不可用": "Dịch vụ chưa khởi động lại: API loại bỏ không khả dụng",
"已弃用 {anchor} 的归档图 {file}(挪到 {dir})": "Đã loại bỏ ảnh lưu trữ {file} của {anchor} (chuyển tới {dir})",
