"天顶/天底不成色带(行方差 {top}/{bot})且左右缘接不上(接缝比 {seam})": "Đỉnh/đáy không thành dải màu (phương sai hàng {top}/{bot}) và mép trái/phải không khớp (tỉ lệ mối nối {seam})",
"左右缘接不上(接缝比 {seam} > {limit}),且机位 {cams} 的视域跨过接缝,接缝会落进背景图": "Mép trái/phải không khớp (tỉ lệ mối nối {seam} > {limit}) và các máy quay {cams} nhìn qua mối nối, nên mối nối sẽ lọt vào phông nền",
"近地前景偏实(底部/中段横向细节比 {nadir})": "Tiền cảnh sát đất quá đặc (tỉ lệ chi tiết ngang đáy/giữa {nadir})",
"近地前景偏实(底部/中段横向细节比 {nadir}),俯拍机位 {cams} 的背景图留意地面纹理尺度": "Tiền cảnh sát đất quá đặc (tỉ lệ chi tiết ngang đáy/giữa {nadir}); chú ý tỉ lệ vân mặt đất trong phông nền của các máy quay góc cao {cams}",
"左右缘接不上(接缝比 {seam} > {limit})": "Mép trái/phải không khớp (tỉ lệ mối nối {seam} > {limit})",
"左右缘接不上(接缝比 {seam} > {limit}),机位 {cams} 的视域跨过接缝,其背景图留意接缝": "Mép trái/phải không khớp (tỉ lệ mối nối {seam} > {limit}); các máy quay {cams} nhìn qua mối nối, chú ý trong phông nền của chúng",
"请在预览页核对": "hãy kiểm tra trên trang xem trước",
"成图边缘过密,对齐度指标失效": "Ảnh quá dày cạnh; chỉ số căn khớp không có ý nghĩa",
"白模轮廓只有 {aligned} 在成图里找得到(错位基线 {null}):若成图是别的视点 / 建筑外观请重出;暗场、岩洞等墙顶墙角不成线的空间属正常,目视对照白模全景即可": "Chỉ tìm thấy {aligned} đường viền whitebox trong ảnh (đường cơ sở lệch {null}): làm lại nếu ảnh là góc nhìn khác hoặc ngoại thất; cảnh tối, hang động và không gian không có đường mép/góc tường rõ là bình thường, chỉ cần đối chiếu bằng mắt với toàn cảnh whitebox",
"成图与白模轮廓对齐度不高于错位基线(对齐 {aligned} / 基线 {null}),请在预览页对照白模全景核对": "Độ khớp của ảnh với đường viền whitebox không vượt đường cơ sở lệch (khớp {aligned} / cơ sở {null}); đối chiếu với toàn cảnh whitebox trên trang xem trước",
