"首帧": "Khung hình đầu",
"工位建议": "Đề xuất của trạm",
"成对运镜": "Chuyển động máy ghép đôi",
"声桥默认": "Mặc định cầu âm",
"声先入": "Âm vào trước (J-cut)",
"声延续": "Âm kéo dài (L-cut)",
"底床": "Nền",
"画外台词": "Lời thoại ngoài khung",
"声桥": "Cầu âm",
"应用声桥": "Áp dụng cầu âm",
"声桥只配无插入段/无黑场的硬切或叠化": "Cầu âm chỉ dùng cho cắt thẳng/chồng mờ không có đoạn chèn/giữ đen",
"需声画分离开启且切点旁有画外句": "Cần bật tách âm-hình và có lời thoại ngoài khung cạnh điểm cắt",
"把声桥写进本边界的设计(decide action=design),机检 transition_sound_bridge_valid": "Ghi cầu âm vào thiết kế ranh giới này (decide action=design); kiểm tra transition_sound_bridge_valid",
"声桥时长需在 0.1–1.5 秒之间": "Độ dài cầu âm phải trong 0.1–1.5 giây",
"声桥默认时长需在 0.1–1.5 秒之间": "Độ dài cầu âm mặc định phải trong 0.1–1.5 giây",
"组边界的声桥(J/L-cut)默认值:声先入 = 下组声音提前压在本组尾画面上;声延续 = 本组声音拖过切点压在下组首画面上。承载「底床」= 只用去人声后的环境声预滚/延续,画面与口型不动;「画外台词」= 让切点旁的画外句跨切点,需声画分离开启且切点旁有画外句。电影感模式自动给建议,自定义模式按「边界处理」里的声先入/声延续出,极简模式不出;每处可在分镜预览页过场卡改": "Mặc định cầu âm ranh giới nhóm (J/L-cut): âm vào trước = âm nhóm sau vào sớm trên hình cuối nhóm này; âm kéo dài = âm nhóm này kéo qua điểm cắt trên hình đầu nhóm sau. «Nền» = chỉ tiếng môi trường đã tách giọng chạy trước/kéo dài, hình và khẩu hình không đổi; «lời thoại ngoài khung» = lời ngoài khung cạnh điểm cắt vượt qua cắt, cần bật tách âm-hình và có lời đó. Chế độ điện ảnh tự đề xuất, tùy chỉnh theo lựa chọn ở «xử lý ranh giới», tối giản không dùng; từng chỗ sửa trên thẻ chuyển cảnh của trang xem trước phân cảnh",
"音先入": "Âm thanh vào trước (J-cut)",

