"添加文件:选择本机文件,不上传,只把绝对路径附在消息里发给 Agent(Shift+点击可手填路径)": "Thêm tệp: chọn tệp trên máy; không tải lên, chỉ nối đường dẫn tuyệt đối vào tin nhắn gửi cho agent (Shift+bấm để nhập đường dẫn)",
